<?php
/** TEMP PS S1610 run e9d — D: deploy darbalaukis v3.10.3 (3/3) + naujas mu-plugin petshop-kliento-siuntos.php v1.0; R: recon naujame procese (kliento_siuntos + paskyros blokas kaip klientas 5787) */
add_action('init', function(){
  if (!isset($_GET['ps_e9d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e9d'])); $o=array('v'=>'run e9d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $c3='';
    $p1=@file_get_contents($bk.'/dl-v3103.part1'); $p2=@file_get_contents($bk.'/dl-v3103.part2'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen($c3));
    $code=base64_decode($p1.$p2.$c3,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='30faf7f378a932d0bbf98cea74d04ed3') { $o['STOP']='darbalaukio md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t); $o['buvo_bytes']=filesize($t);
    if (preg_match("/VERSIJA = '([\d.]+)'/",file_get_contents($t),$m)) $o['buvo_v']=$m[1];
    if ($o['buvo']!=='03330ef26ff82f4022dea45f16771d0a') { $o['STOP']='gyvas darbalaukis ne v3.10.2 (md5 '.$o['buvo'].')'; $J($o); }
    // naujas mu-plugin
    $k=base64_decode('',true); $o['ks_bytes']=strlen((string)$k); $o['ks_md5']=md5((string)$k);
    if ($o['ks_md5']!=='dd636b5c7e69a6af62876810303a91ec') { $o['STOP']='kliento-siuntos md5 nesutampa'; $J($o); }
    try { token_get_all($k, TOKEN_PARSE); $o['ks_token']='ok'; } catch (Throwable $e) { $o['STOP']='ks token: '.$e->getMessage(); $J($o); }
    $kt=WPMU_PLUGIN_DIR.'/petshop-kliento-siuntos.php'; $o['ks_buvo']=file_exists($kt)?md5_file($kt):null;
    if ($o['ks_buvo']) { $o['ks_backup']=copy($kt,$bk.'/petshop-kliento-siuntos-BACKUP-'.date('Y-m-d-His').'.php'); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v'.str_replace('.','',$o['buvo_v']??'x').'-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); $o['po_bytes']=filesize($t);
    $o['ks_rasyta']=file_put_contents($kt,$k); $o['ks_po']=md5_file($kt);
    @unlink($bk.'/dl-v3103.part1'); @unlink($bk.'/dl-v3103.part2');
    $o['backups']=array_values(array_filter(scandir($bk),function($x){return strpos($x,'petshop-darbalaukis-v')===0||strpos($x,'kliento')!==false;}));
  }
  if($f==='R'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['ks']=class_exists('Petshop_Kliento_Siuntos')?Petshop_Kliento_Siuntos::VERSIJA:'NĖRA';
    $o['metodas']=method_exists('Petshop_Darbalaukis','kliento_siuntos');
    global $wp_filter; $o['hookai']=array(); if(!empty($wp_filter['woocommerce_order_details_before_order_table'])){ foreach($wp_filter['woocommerce_order_details_before_order_table']->callbacks as $pr=>$cbs){ foreach($cbs as $cb){ $fn=$cb['function']; $o['hookai'][]=$pr.': '.(is_array($fn)?(is_object($fn[0])?get_class($fn[0]):$fn[0]).'::'.$fn[1]:(is_string($fn)?$fn:'closure')); } } }
    foreach(array(35421,35440,35450,35775,35418) as $oid){ $ord=wc_get_order($oid); if(!$ord){ $o['ks_'.$oid]='nera'; continue; } $s=Petshop_Darbalaukis::kliento_siuntos($ord); $o['ks_'.$oid]=array('st'=>$ord->get_status(),'cust'=>$ord->get_customer_id(),'siuntos'=>array_map(function($x){ $x['prekes']=array_map(function($q){return $q['q'].'x '.mb_substr($q['n'],0,25);},$x['prekes']); return $x; },$s)); }
    $o['html_35421']=Petshop_Kliento_Siuntos::html(Petshop_Darbalaukis::kliento_siuntos(wc_get_order(35421)));
    // paskyra kaip klientas 5787 (loopback)
    $uid=5787; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'logged_in',$tok))));
    foreach(array(35421,35440) as $oid){ $u=wc_get_endpoint_url('view-order',$oid,wc_get_page_permalink('myaccount')); $r=wp_remote_get($u,array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); if(is_wp_error($r)){ $o['pask_'.$oid]=$r->get_error_message(); continue; } $b=wp_remote_retrieve_body($r); $x=array('code'=>wp_remote_retrieve_response_code($r),'url'=>$u,'blokas'=>strpos($b,'class="ps-siuntos"')!==false);
      if(preg_match('/<section class="ps-siuntos".*?<\/section>/s',$b,$mm)) $x['tekstas']=trim(preg_replace('/\s+/',' ',wp_strip_all_tags($mm[0])));
      if(preg_match('/<section class="woocommerce-order-details">(.{0,400})/s',$b,$mm)) $x['pries_lentele']=trim(preg_replace('/\s+/',' ',wp_strip_all_tags($mm[1])));
      $o['pask_'.$oid]=$x; }
    // svečio užsakymas (#35775) — blokas NEturi rodytis net savininkui nesant
    $o['rodyti_35775_svecias']=Petshop_Kliento_Siuntos::rodyti(wc_get_order(35775));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
});
